CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,display_name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'PLAYER',password_hash TEXT,disabled INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS topics(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES users(id),category TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,locked INTEGER NOT NULL DEFAULT 0,pinned INTEGER NOT NULL DEFAULT 0,deleted INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS replies(id TEXT PRIMARY KEY,topic_id TEXT NOT NULL REFERENCES topics(id) ON DELETE CASCADE,author_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,deleted INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lobbies(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,description TEXT NOT NULL,genre TEXT NOT NULL,slots INTEGER NOT NULL,energy TEXT NOT NULL,rank TEXT NOT NULL,visibility TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',invite_code TEXT UNIQUE NOT NULL,world_json TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members(lobby_id TEXT NOT NULL REFERENCES lobbies(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL,joined_at TEXT NOT NULL,PRIMARY KEY(lobby_id,user_id));
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,lobby_id TEXT NOT NULL REFERENCES lobbies(id) ON DELETE CASCADE,author_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS characters(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,data_json TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS character_bindings(lobby_id TEXT NOT NULL REFERENCES lobbies(id) ON DELETE CASCADE,character_id TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES users(id),approved INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(lobby_id,character_id));
CREATE TABLE IF NOT EXISTS publications(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tickets(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ticket_replies(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,author_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,target_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS topics_feed ON topics(deleted,category,updated_at);
CREATE INDEX IF NOT EXISTS replies_thread ON replies(topic_id,created_at);
CREATE INDEX IF NOT EXISTS lobby_search ON lobbies(visibility,status,updated_at);
CREATE INDEX IF NOT EXISTS chat_feed ON messages(lobby_id,created_at);
CREATE INDEX IF NOT EXISTS owned_characters ON characters(owner_id);
CREATE INDEX IF NOT EXISTS owned_tickets ON tickets(author_id);
